/**
 * Render branding and downloads.
 *
 * Two promises are checked here: every rendered image that leaves the app
 * carries "Generated by GD Suits", and nothing that is not a render ever does
 * - a client's own photograph must come back byte for byte as it went in.
 * And every image can be saved, and saved again.
 */
const { app, BrowserWindow, dialog, nativeImage } = require('electron');
const fs = require('fs');
const os = require('os');
const path = require('path');
require('./fresh.js').freshUserData(app);

// The save dialog is the tailor's choice of destination. Here it is scripted,
// and every call is recorded so a refused request can be shown never to reach it.
const OUT = fs.mkdtempSync(path.join(os.tmpdir(), 'gd-dl-'));
const dialogCalls = [];
let nextAnswer = null;
dialog.showSaveDialog = async (_win, opts) => {
  dialogCalls.push(opts);
  if (nextAnswer === 'cancel') return { canceled: true };
  return { canceled: false, filePath: nextAnswer ?? path.join(OUT, path.basename(opts.defaultPath)) };
};

require('../electron/main.js');
const db = require('../electron/db.js');
const storage = require('../electron/storage.js');
const brand = require('../electron/brand.js');

let pass = 0, fail = 0;
const log = (...a) => process.stdout.write(a.join(' ') + '\n');
const check = (ok, label, detail = '') => { ok ? (pass++, log('  ✓', label)) : (fail++, log('  ✗ FAIL:', label, detail)); };
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

/** A solid image, so any change to a pixel is unmistakably the badge. */
function solid(width, height, [b, g, r], format = 'png') {
  const px = Buffer.alloc(width * height * 4);
  for (let i = 0; i < px.length; i += 4) { px[i] = b; px[i + 1] = g; px[i + 2] = r; px[i + 3] = 255; }
  const img = nativeImage.createFromBitmap(px, { width, height });
  return format === 'jpeg' ? img.toJPEG(95) : img.toPNG();
}
const pixel = (buf, x, y) => {
  const img = nativeImage.createFromBuffer(buf);
  const { width } = img.getSize();
  const i = (y * width + x) * 4;
  return [...img.toBitmap().subarray(i, i + 4)];
};
const size = (buf) => nativeImage.createFromBuffer(buf).getSize();
const isPng = (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
const isJpeg = (b) => b[0] === 0xff && b[1] === 0xd8;

app.whenReady().then(async () => {
  await wait(2400);
  const win = BrowserWindow.getAllWindows()[0];
  const js = (c) => win.webContents.executeJavaScript(c);

  log('=== the blend, on the pixels where it matters ===');
  // White at 50% alpha, premultiplied, which is how PNG-decoded bitmaps arrive.
  const half = Buffer.from([128, 128, 128, 128]);
  const overBlack = brand.blendInto(Buffer.from([0, 0, 0, 255]), 1, 1, half, 1, 1, 0, 0);
  check(JSON.stringify([...overBlack]) === '[128,128,128,255]', 'half-white over black is mid grey, not dark grey', JSON.stringify([...overBlack]));
  const overWhite = brand.blendInto(Buffer.from([255, 255, 255, 255]), 1, 1, half, 1, 1, 0, 0);
  check(JSON.stringify([...overWhite]) === '[255,255,255,255]', 'half-white over white stays white', JSON.stringify([...overWhite]));
  const clear = brand.blendInto(Buffer.from([10, 20, 30, 255]), 1, 1, Buffer.from([0, 0, 0, 0]), 1, 1, 0, 0);
  check(JSON.stringify([...clear]) === '[10,20,30,255]', 'a transparent badge pixel leaves the image alone');
  const edge = Buffer.alloc(2 * 2 * 4, 7);
  brand.blendInto(edge, 2, 2, Buffer.alloc(4 * 4 * 4, 255), 4, 4, 1, 1);
  check(edge.length === 16 && [...edge.subarray(0, 4)].every((v) => v === 7), 'a badge hanging off the edge writes nothing past it');
  // The blend is only right if this holds - pin it so an Electron upgrade that
  // changes it fails here rather than quietly greying every badge.
  const decoded = nativeImage.createFromBuffer(nativeImage.createFromBitmap(Buffer.from([255, 255, 255, 128]), { width: 1, height: 1 }).toPNG()).toBitmap();
  check(JSON.stringify([...decoded]) === '[128,128,128,128]', 'Electron still hands back PNG bitmaps premultiplied', JSON.stringify([...decoded]));

  log('\n=== stamping a whole image ===');
  const grey = solid(800, 1000, [128, 128, 128]);
  const stamped = brand.stamp(grey);
  check(JSON.stringify(size(stamped)) === '{"width":800,"height":1000}', 'the image keeps its size', JSON.stringify(size(stamped)));
  check(JSON.stringify(pixel(stamped, 20, 20)) === '[128,128,128,255]', 'the top-left is untouched');
  check(JSON.stringify(pixel(stamped, 790 - 20 - 40, 980 - 30)) !== '[128,128,128,255]', 'the bottom-right carries the badge');
  check(isPng(stamped), 'a PNG comes back as a PNG');
  check(isJpeg(brand.stamp(solid(400, 500, [90, 90, 90], 'jpeg'), 'jpeg')), 'a JPEG comes back as a JPEG, so its filename stays honest');
  let threw = false;
  try { brand.stamp(Buffer.from('not an image')); } catch { threw = true; }
  check(threw, 'something that is not an image is refused');

  // ---- a real order, with a render and a client photo on it ----
  const clientId = db.upsertClient({ name: 'Brand', surname: 'Test', contact: '', email: '' });
  const projectId = db.createProject({ clientId, title: 'Brand test' });
  const scope = storage.scopeForProject(projectId);
  const renderBytes = solid(640, 800, [120, 110, 100]);
  const renderFile = storage.saveImage(scope, renderBytes, 'image/png', 'render');
  db.addRender({ projectId, view: 'front', filename: renderFile });
  const photoBytes = solid(300, 400, [40, 160, 220]);
  await js(`window.gd.photos.add({ projectId: ${projectId}, slot: 'front',
    dataUrl: 'data:image/png;base64,${photoBytes.toString('base64')}' })`);
  const photoFile = db.getProject(projectId).photos[0].filename;
  const photoOnDisk = storage.readImage(scope, photoFile);
  const renderUrl = `gdmedia://media/${scope}/${encodeURIComponent(renderFile)}`;
  const photoUrl = `gdmedia://media/${scope}/${encodeURIComponent(photoFile)}`;
  const download = (url, name) => js(`window.gd.media.download({ url: ${JSON.stringify(url)}, name: ${JSON.stringify(name ?? '')} })
    .then(r => JSON.stringify(r.ok ? r.data : { error: r.error.message }))`).then(JSON.parse);

  log('\n=== downloading a render ===');
  nextAnswer = null;
  const r1 = await download(renderUrl, 'GD-2026-0001 front render');
  check(r1.saved === true && r1.branded === true, 'it saves, and says it was branded', JSON.stringify(r1));
  const saved1 = fs.readFileSync(path.join(OUT, r1.name));
  check(!saved1.equals(renderBytes), 'the saved copy is not the unbadged original');
  check(JSON.stringify(size(saved1)) === JSON.stringify(size(renderBytes)), 'at the same size');
  check(storage.readImage(scope, renderFile).equals(renderBytes), 'and the render on disk is still clean, ready to refine');
  const r2 = await download(renderUrl, 'again');
  check(r2.saved && fs.readFileSync(path.join(OUT, r2.name)).equals(saved1), 'it can be downloaded again, identically');
  const r3 = await download(`${renderUrl}?branded=1`, 'from the preview');
  check(r3.saved && fs.readFileSync(path.join(OUT, r3.name)).equals(saved1),
    'the address the preview shows downloads the same single badge, not two');

  log('\n=== downloading anything that is not a render ===');
  const p1 = await download(photoUrl, 'Brand Test front');
  check(p1.saved === true && p1.branded === false, 'a client photo saves, unbranded', JSON.stringify(p1));
  check(fs.readFileSync(path.join(OUT, p1.name)).equals(photoOnDisk), 'byte for byte as it was taken');
  const p2 = await download(`${photoUrl}?branded=1`, 'asked for a badge');
  check(p2.saved && fs.readFileSync(path.join(OUT, p2.name)).equals(photoOnDisk),
    'asking for a badge on a photo is ignored - it was not generated by anyone');

  log('\n=== what a hostile page gets ===');
  const before = dialogCalls.length;
  for (const [label, url] of [
    ['a path that climbs out of the media folder', `gdmedia://media/${scope}/..%2F..%2F..%2Fsecrets.json`],
    ['a file:// address', 'file:///etc/passwd'],
    ['a made-up scope', 'gdmedia://media/../etc/hosts'],
    ['an image that does not exist', `gdmedia://media/${scope}/render-nope.png`],
  ]) {
    const r = await download(url);
    check(r.error === 'Image not found.', `${label}: "not found"`, JSON.stringify(r));
  }
  check(dialogCalls.length === before, 'and not one of them got as far as a save dialog');
  nextAnswer = null;
  const named = await download(photoUrl, '../../evil/..\\\\x');
  const offered = dialogCalls[dialogCalls.length - 1].defaultPath;
  check(path.dirname(offered) === app.getPath('downloads') && !/[\\\\/]/.test(path.basename(offered)),
    'a name with path separators cannot steer the default location', offered);
  nextAnswer = 'cancel';
  const files = fs.readdirSync(OUT).length;
  const c = await download(renderUrl);
  check(c.saved === false && fs.readdirSync(OUT).length === files, 'cancelling writes nothing');
  nextAnswer = null;

  log('\n=== what the preview displays ===');
  const shown = await js(`(async () => {
    const get = async (u) => new Uint8Array(await (await fetch(u)).arrayBuffer()).join(',');
    const branded = window.gd.brandedRender(${projectId}, ${JSON.stringify(renderFile)});
    return JSON.stringify({
      url: branded,
      renderDiffers: (await get(branded)) !== (await get(${JSON.stringify(renderUrl)})),
      photoSame: (await get(${JSON.stringify(photoUrl + '?branded=1')})) === (await get(${JSON.stringify(photoUrl)})),
    });
  })()`).then(JSON.parse);
  check(/\?branded=1$/.test(shown.url), 'the preview asks for the badged render');
  check(shown.renderDiffers, 'and gets it');
  check(shown.photoSame, 'while a photo asked for the same way comes back plain');

  log('\n=== exporting the client file ===');
  const exportDir = path.join(OUT, 'export');
  nextAnswer = exportDir;
  await js(`window.gd.project.export({ projectId: ${projectId}, html: '<html></html>' })`);
  nextAnswer = null;
  const exRender = fs.readFileSync(path.join(exportDir, 'images', renderFile));
  check(!exRender.equals(renderBytes) && isPng(exRender), 'the render leaves badged, under the name the order form links to');
  check(fs.readFileSync(path.join(exportDir, 'images', photoFile)).equals(photoOnDisk), 'the photo leaves untouched');

  log('\n=== in the interface ===');
  // The order was seeded straight into the database after the window had
  // already listed orders, so the list has to be fetched again to show it.
  win.webContents.reload(); await wait(2200);
  const ui = await js(`(async () => {
    const wait = ms => new Promise(r => setTimeout(r, ms));
    [...document.querySelectorAll('.nav-item')].find(b => b.textContent.includes('Orders')).click(); await wait(900);
    [...document.querySelectorAll('tbody tr')].find(r => r.textContent.includes('Brand Test')).click(); await wait(1000);
    const tab = (t) => [...document.querySelectorAll('.step-tab')].find(x => x.textContent.includes(t));
    tab('Capture').click(); await wait(900);
    const slotDl = [...document.querySelectorAll('.photo-slot.filled .photo-actions button')].some(b => b.textContent.trim() === 'Download');
    tab('Preview').click(); await wait(1200);
    const stageImg = document.querySelector('.render-stage img')?.getAttribute('src') || '';
    const btn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === 'Download render');
    btn?.click(); await wait(1200);
    return JSON.stringify({ slotDl, stageImg, hasBtn: !!btn });
  })()`).then(JSON.parse);
  check(ui.slotDl, 'a filled photo slot offers Download');
  check(/\?branded=1/.test(ui.stageImg), 'the preview shows the badged render', ui.stageImg);
  check(ui.hasBtn, 'and offers "Download render"');
  const lastSave = dialogCalls[dialogCalls.length - 1];
  check(/render/i.test(lastSave?.title || '') && /Brand-test|GD|render/i.test(path.basename(lastSave?.defaultPath || '')),
    'clicking it opens the save dialog for the render', JSON.stringify(lastSave?.defaultPath));

  fs.rmSync(OUT, { recursive: true, force: true });
  log(`\n${fail === 0 ? 'ALL BRANDING CHECKS PASSED' : 'FAILED'} — ${pass} passed, ${fail} failed`);
  app.exit(fail === 0 ? 0 : 1);
}).catch((e) => { log('HARNESS FAIL', e.stack); app.exit(1); });
